#pragma once
#include "kstationPanelHardwareTask.h"
#include "kstationNativeMidiPump.h"
#include <variant>
namespace kstation {
class NativePanelHardware final {
 using P=PanelPublishTask;using B=PanelBitsTask;using M=PanelModeTask;using R=PanelResetTask;
 struct Job{std::variant<P,B,M,R>task;};
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,2>CodeRanges{{{0x2104,0x2186},{0x21f0,0x2284}}};
 static bool candidate(unsigned at){return (at>=0x2104&&at<0x2186)||(at>=0x21f0&&at<0x2284);}bool active()const{return depth_!=0;}void reset(){depth_=0;steps_=0;}uint64_t steps()const{return steps_;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x2104)j.task.emplace<R>();else if(at==0x2130)j.task.emplace<P>();else if(at==0x21f0){if(uint8_t(c.reg8(14))>8)return false;j.task.emplace<B>(uint8_t(c.reg8(14)),uint8_t(c.reg8(6)));}else if(at==0x2248||at==0x2266)j.task.emplace<M>(uint8_t(c.reg8(14)),at==0x2266);else return false;if(depth_==jobs_.size())throw std::logic_error("Native K panel hardware capacity");jobs_[depth_++]=j;}
  auto&j=jobs_[depth_-1];resume(j);if(at!=boundary(j))throw std::logic_error("Native K panel hardware boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
  std::visit([&](auto&t){using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,P>)t.advanceBefore(cost,cr,[&](P::Read field,unsigned index)->unsigned{if(field==P::Read::Strobe)return uint8_t(c.read8(0xffffd3));auto reg=field==P::Read::Mirror||field==P::Read::Port?6:14;auto address=field==P::Read::Mirror?0xfffe88+index:field==P::Read::Flags?0xfffe8c:0xffffd2;c.reg8(reg)=c.read8(address);if(field==P::Read::Mirror){++c.reg32(5);c.clockI(2);}val(c,c.reg8(reg));return uint8_t(c.reg8(reg));},[&](P::Write field,unsigned value){unsigned address=field==P::Write::Data?0xffffc7:field==P::Write::Mux||field==P::Write::Strobe?0xffffd3:field==P::Write::Port?0xffffd2:0xfffe8e;if(field!=P::Write::Strobe)val(c,c.reg8(field==P::Write::Mux?14:6));c.write8(int8_t(value),address);});else if constexpr(std::is_same_v<J,B>)t.advanceBefore(cost,cr,[&](B::Read field)->unsigned{auto address=field==B::Read::Set?0xa966+t.index()*8:field==B::Read::Clear?0xa96a+t.index()*8:0xfffe88;auto reg=field==B::Read::Set?1:field==B::Read::Clear?0:2;c.reg32(reg)=int32_t(c.read32(address));if(field==B::Read::Set){c.reg32(0)=int32_t(uint32_t(c.reg32(0))+4);c.clockI(2);}val(c,c.reg32(reg));return uint32_t(c.reg32(reg));},[&](unsigned value){c.write32(int32_t(value),0xfffe88);val(c,c.reg32(2));});else if constexpr(std::is_same_v<J,M>)t.advanceBefore(cost,cr,[&]{c.reg8(8)=c.read8(0xfffe8c);val(c,c.reg8(8));return uint8_t(c.reg8(8));},[&](unsigned value){val(c,c.reg8(8));c.write8(int8_t(value),0xfffe8c);});else t.advanceBefore(cost,cr,[&](unsigned index,unsigned value){val(c,c.reg8(8));c.write8(int8_t(value),0xfffe8f+index);});},j.task);
  if(c.cycles-begin!=cost)throw std::logic_error("Native K panel hardware clocks differ");auto done=std::visit([](const auto&t){return t.complete();},j.task);if(done)--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;
 }
private:
 static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void dec(Stage1Cpu&c,unsigned r,bool word=false){int old=word?c.reg16(r):c.reg8(r),v=old-1;val(c,v);if((old&~v)&(word?0x8000:0x80))c.ccr|=2;if(word)c.reg16(r)=int16_t(v);else c.reg8(r)=int8_t(v);}static void inc(Stage1Cpu&c,unsigned r){int old=c.reg8(r),v=old+1;val(c,v);if((~old&v)&0x80)c.ccr|=2;c.reg8(r)=int8_t(v);}
 static bool waiting(const Job&j){return std::visit([](const auto&t){using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,P>)return false;else return t.awaiting();},j.task);}static void resume(Job&j){std::visit([](auto&t){using J=std::decay_t<decltype(t)>;if constexpr(!std::is_same_v<J,P>)if(t.awaiting())t.resume();},j.task);}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,P>){static constexpr unsigned a[]={0x2130,0x2134,0x2138,0x213e,0x2140,0x2144,0x2146,0x2148,0x214a,0x214e,0x2150,0x2154,0x2156,0x2158,0x215a,0x215e,0x2160,0x2162,0x2164,0x216a,0x216c,0x216e,0x2170,0x2172,0x2174,0x2176,0x217c,0x2180,0x2184,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<J,B>){static constexpr unsigned a[]={0x21f0,0x21f4,0x21f8,0x21fc,0x21fe,0x2200,0x2202,0x2204,0x2206,0x220c,0x2210,0x2214,0x221c,0x2220,0x2222,0x2224,0x2226,0x2228,0x222c,0x2234,0x2238,0x223a,0x223e,0x2242,0x2246,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<J,M>){static constexpr unsigned a[]={0x2248,0x224a,0x2250,0x2252,0x2254,0x2256,0x2258,0x225e,0x2262,0x2264,0};return a[unsigned(t.stage())]+(t.first()?0x1e:0);}else{static constexpr unsigned a[]={0x2104,0x2106,0x2108,0x210c,0x210e,0x2110,0x2112,0x2116,0x211a,0x211c,0x2122,0x2128,0x212e,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){switch(boundary(j)){case 0x2138:case 0x2164:case 0x2176:case 0x2206:case 0x224a:case 0x2258:case 0x2268:case 0x2276:case 0x211c:case 0x2122:case 0x2128:return 6;case 0x2214:case 0x222c:return 8;case 0x2130:case 0x2134:case 0x2140:case 0x214a:case 0x2150:case 0x215a:case 0x217c:case 0x2180:case 0x21f0:case 0x21f4:case 0x21f8:case 0x220c:case 0x2210:case 0x221c:case 0x2228:case 0x2234:case 0x223a:case 0x223e:case 0x2242:case 0x225e:case 0x227c:case 0x2108:case 0x2112:case 0x2116:return 4;default:return 2;}}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,last);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);if(auto*t=std::get_if<P>(&j.task)){using Q=P::Stage;switch(t->stage()){case Q::ReadMirror:cr.read=bus(0xfffe88+t->index(),1,last);break;case Q::WriteData:case Q::WriteMux:case Q::WritePort:cr.write=1;break;case Q::ClearStrobe:case Q::SetStrobe:cr.read=cr.write=1;break;case Q::ReadFlags:cr.read=bus(0xfffe8c,1,last);break;case Q::ReadPort:cr.read=1;break;case Q::WriteMirror:cr.write=bus(0xfffe8e,1,c.writeHistory());break;default:break;}}else if(auto*t=std::get_if<B>(&j.task)){using Q=B::Stage;switch(t->stage()){case Q::ReadSet:cr.read=bus(0xa966+t->index()*8,4,last);break;case Q::ReadClear:cr.read=bus(0xa96a+t->index()*8,4,last);break;case Q::ReadMirror:cr.read=bus(0xfffe88,4,last);break;case Q::WriteMirror:cr.write=bus(0xfffe88,4,c.writeHistory());break;default:break;}}else if(auto*t=std::get_if<M>(&j.task)){if(t->stage()==M::Stage::Read)cr.read=bus(0xfffe8c,1,last);else if(t->stage()==M::Stage::Write)cr.write=bus(0xfffe8c,1,c.writeHistory());}else if(auto*t=std::get_if<R>(&j.task)){auto s=t->stage();if(s==R::Stage::WriteFirstCount||s==R::Stage::WriteSecondCount||s==R::Stage::WriteNoticeCount)cr.write=bus(s==R::Stage::WriteFirstCount?0xfffe8f:s==R::Stage::WriteSecondCount?0xfffe90:0xfffe91,1,c.writeHistory());}return cr;}
 static void project(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<P>(&j.task)){using Q=P::Stage;switch(t->stage()){case Q::RetainPointer:push(c,5,false);break;case Q::RetainData:push(c,6,false);break;case Q::BindMirror:c.reg32(5)=0xfffe88;val(c,c.reg32(5));break;case Q::BindMux:c.reg8(14)=0x60;val(c,0x60);break;case Q::Count:c.reg16(14)=4;val(c,4);break;case Q::RetainDelay:push(c,0,true);break;case Q::BindDelay:c.reg16(0)=3;val(c,3);break;case Q::TickDelay:dec(c,0,true);break;case Q::RestoreDelay:pop(c,0,true);break;case Q::AdvanceMux:c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),8,8,false));break;case Q::DecrementCount:dec(c,14,true);break;case Q::ShiftFirst:case Q::ShiftSecond:{auto old=uint8_t(c.reg8(14));c.ccr=uint8_t((c.ccr&~1)|(old&1));c.reg8(14)=int8_t(old>>1);val(c,c.reg8(14));break;}case Q::CopyFirst:c.reg8(6)=int8_t((uint8_t(c.reg8(6))&~16u)|((c.ccr&1)?16:0));break;case Q::CopySecond:c.reg8(6)=int8_t((uint8_t(c.reg8(6))&~32u)|((c.ccr&1)?32:0));break;case Q::RestoreData:pop(c,6,false);break;case Q::RestorePointer:pop(c,5,false);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<B>(&j.task)){using Q=B::Stage;switch(t->stage()){case Q::RetainIndex:push(c,0,false);break;case Q::RetainMask:push(c,1,false);break;case Q::RetainMirror:push(c,2,false);break;case Q::RetainInput:push(c,6,true);break;case Q::CopyIndex:c.reg8(8)=c.reg8(14);val(c,c.reg8(8));break;case Q::BindScale:c.reg8(0)=8;val(c,8);break;case Q::Multiply:c.reg16(0)=int16_t(uint8_t(c.reg8(8))*uint8_t(c.reg8(0)));c.clockI(12);break;case Q::Extend:c.reg32(0)=uint16_t(c.reg16(0));val(c,c.reg32(0));break;case Q::BindTable:c.reg32(0)=int32_t(midi_projection::arithmetic(c,c.reg32(0),0xa966,32,false));break;case Q::ClearBits:c.reg32(2)&=c.reg32(0);val(c,c.reg32(2));break;case Q::DecrementSelection:dec(c,6);break;case Q::SelectSelection:break;case Q::Shift:{auto old=uint32_t(c.reg32(1));c.ccr=uint8_t((c.ccr&~1)|((old&0x80000000)?1:0));c.reg32(1)=int32_t(old<<1);val(c,c.reg32(1));break;}case Q::Merge:c.reg32(2)|=c.reg32(1);val(c,c.reg32(2));break;case Q::Publish:midi_projection::call(c,0x2130,0x2238,true);break;case Q::RestoreInput:pop(c,6,true);break;case Q::RestoreMirror:pop(c,2,false);break;case Q::RestoreMask:pop(c,1,false);break;case Q::RestoreIndex:pop(c,0,false);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<M>(&j.task)){using Q=M::Stage;auto offset=t->first()?0x1e:0;switch(t->stage()){case Q::Retain:push(c,0,true);break;case Q::Mask:c.reg8(8)&=t->first()?2:1;val(c,c.reg8(8));break;case Q::TestInput:val(c,c.reg8(14));break;case Q::Set:c.reg8(8)|=t->first()?1:2;val(c,c.reg8(8));break;case Q::Publish:midi_projection::call(c,0x2130,0x2262+offset,true);break;case Q::Restore:pop(c,0,true);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<R>(&j.task)){using Q=R::Stage;switch(t->stage()){case Q::Count:c.reg8(8)=9;val(c,9);break;case Q::Clear:c.reg16(6)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::WriteBits:midi_projection::call(c,0x21f0,0x210c,true);break;case Q::Advance:inc(c,14);break;case Q::Decrement:dec(c,8);break;case Q::WriteMode:midi_projection::call(c,0x2248,0x2116,true);break;case Q::WriteFirst:midi_projection::call(c,0x2266,0x211a,true);break;case Q::ClearCount:c.reg8(8)=0;val(c,0);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
 }
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;
};
}
